export function calculateBrazilMapResults(
  result: {
    candidates: Array<{
      number: string;
      votes: number;
      percentage: number;
      ballotName: string;
    }>;
    percentageSectionsTotalized?: number;
  } | null,
  official?: BrazilMapOfficialData | null,
): BrazilMapSummary {
  if (official) return calculateOfficialMapResults(official);

  const c22 = result?.candidates?.find((c) => c.number === "22");
  const c13 = result?.candidates?.find((c) => c.number === "13");

  // National percentages or baseline
  const natP22 = c22
    ? c22.percentage
    : (result?.candidates?.[0]?.percentage ?? 51.5);
  const natP13 = c13
    ? c13.percentage
    : (result?.candidates?.[1]?.percentage ?? 48.5);
  const totalBoth = natP22 + natP13 || 100;
  const ratio22 = (natP22 / totalBoth) * 100;

  // National progress
  const progress = result?.percentageSectionsTotalized ?? 85.0;

  let statesWon22 = 0;
  let statesWon13 = 0;
  let statesTied = 0;
  let electorateWon22 = 0;
  let electorateWon13 = 0;

  const stateResults: Record<string, StateLiveResult> = {};

  for (const [sigla, state] of Object.entries(BRAZIL_STATES_GEO)) {
    // Calibrate baseline according to national trend (mock only)
    const shift = (ratio22 - 50) * 0.8;
    const rawP22 = Math.max(10, Math.min(90, state.base22 + shift));
    const rawP13 = 100 - rawP22;

    const stateTurnout = Math.round(state.electorate * 0.79 * (progress / 100));
    const v22 = Math.round((stateTurnout * rawP22) / 100);
    const v13 = Math.round((stateTurnout * rawP13) / 100);

    const leader: "22" | "13" | "tie" =
      rawP22 > rawP13 ? "22" : rawP13 > rawP22 ? "13" : "tie";

    if (leader === "22") {
      statesWon22++;
      electorateWon22 += state.electorate;
    } else if (leader === "13") {
      statesWon13++;
      electorateWon13 += state.electorate;
    } else {
      statesTied++;
    }

    // Cities calculations (mock only)
    const citiesResults = state.cities.map((city) => {
      const cityBase22 = city.base22 ?? state.base22;
      const cP22 = Math.max(15, Math.min(85, cityBase22 + shift));
      const cP13 = 100 - cP22;
      const cTurnout = Math.round(city.electorate * 0.8 * (progress / 100));
      const cv22 = Math.round((cTurnout * cP22) / 100);
      const cv13 = Math.round((cTurnout * cP13) / 100);
      return {
        name: city.name,
        shortName: city.shortName,
        electorate: city.electorate,
        votes22: cv22,
        votes13: cv13,
        percent22: Number(cP22.toFixed(2)),
        percent13: Number(cP13.toFixed(2)),
        leader: (cP22 >= cP13 ? "22" : "13") as "22" | "13",
      };
    });

    stateResults[sigla] = {
      sigla,
      name: state.name,
      region: state.region,
      capital: state.capital,
      electorate: state.electorate,
      sectionsPercent: Number(progress.toFixed(1)),
      votes22: v22,
      votes13: v13,
      percent22: Number(rawP22.toFixed(2)),
      percent13: Number(rawP13.toFixed(2)),
      leader,
      statusLabel:
        progress >= 100
          ? leader === "22"
            ? "FLÁVIO BOLSONARO VENCEU"
            : "LULA VENCEU"
          : leader === "22"
            ? "FLÁVIO BOLSONARO LIDERA"
            : "LULA LIDERA",
      marginPercent: Number(Math.abs(rawP22 - rawP13).toFixed(2)),
      marginVotes: Math.abs(v22 - v13),
      cities: citiesResults,
      official: false,
    };
  }

  const leadingNational =
    statesWon22 > statesWon13 ? "22" : statesWon13 > statesWon22 ? "13" : "tie";

  return {
    statesWon22,
    statesWon13,
    statesTied,
    electorateWon22,
    electorateWon13,
    leadingNational,
    stateResults,
    official: false,
    statesLoaded: 27,
    statesTotal: 27,
    updatedAt: null,
  };
}

function calculateOfficialMapResults(
  official: BrazilMapOfficialData,
): BrazilMapSummary {
  let statesWon22 = 0;
  let statesWon13 = 0;
  let statesTied = 0;
  let electorateWon22 = 0;
  let electorateWon13 = 0;
  let statesLoaded = 0;
  const stateResults: Record<string, StateLiveResult> = {};

  for (const [sigla, state] of Object.entries(BRAZIL_STATES_GEO)) {
    const live = official.states[sigla];
    if (!live) {
      statesTied++;
      stateResults[sigla] = {
        sigla,
        name: state.name,
        region: state.region,
        capital: state.capital,
        electorate: state.electorate,
        sectionsPercent: 0,
        votes22: 0,
        votes13: 0,
        percent22: 0,
        percent13: 0,
        leader: "tie",
        statusLabel: "AGUARDANDO",
        marginPercent: 0,
        marginVotes: 0,
        cities: [],
        official: true,
        final: false,
        updatedAt: null,
        validVotes: 0,
      };
      continue;
    }

    statesLoaded++;
    const votes22 = live.votes22;
    const votes13 = live.votes13;
    const percent22 = live.percent22;
    const percent13 = live.percent13;
    const leader: "22" | "13" | "tie" =
      votes22 > votes13
        ? "22"
        : votes13 > votes22
          ? "13"
          : percent22 > percent13
            ? "22"
            : percent13 > percent22
              ? "13"
              : "tie";

    if (leader === "22") {
      statesWon22++;
      electorateWon22 += state.electorate;
    } else if (leader === "13") {
      statesWon13++;
      electorateWon13 += state.electorate;
    } else {
      statesTied++;
    }

    stateResults[sigla] = {
      sigla,
      name: state.name,
      region: state.region,
      capital: state.capital,
      electorate: state.electorate,
      sectionsPercent: live.sectionsPercent,
      votes22,
      votes13,
      percent22,
      percent13,
      leader,
      statusLabel: leader === "tie" ? "AGUARDANDO" : "LIDERA",
      marginPercent: Number(Math.abs(percent22 - percent13).toFixed(2)),
      marginVotes: Math.abs(votes22 - votes13),
      cities: [],
      official: true,
      final: live.final,
      updatedAt: live.receivedAt,
      validVotes: live.validVotes,
    };
  }

  const leadingNational =
    statesWon22 > statesWon13 ? "22" : statesWon13 > statesWon22 ? "13" : "tie";

  return {
    statesWon22,
    statesWon13,
    statesTied,
    electorateWon22,
    electorateWon13,
    leadingNational,
    stateResults,
    official: true,
    statesLoaded,
    statesTotal: 27,
    updatedAt: official.updatedAt,
  };
}
